   if(!lines.length){root.querySelector('#berr').textContent='No volunteer rows were found below the header.';return}
   const vs=lines.map(line=>{const c=splitLine(line);return{first_name:(c[0]||'').trim(),last_name:(c[1]||'').trim(),gender:(c[2]||'').trim(),email:(c[3]||'').trim(),phone:(c[4]||'').trim(),roles:(c[5]||'').split('|').map(x=>x.trim()).filter(Boolean),active:true}});
