       const msg=section.querySelector('#tasktime-msg'),rows=[];
       tb.querySelectorAll('tr[data-i]').forEach(tr=>{const i=Number(tr.dataset.i),old=slotRows[i]||{};rows.push({id:old.id||'',date:tr.querySelector('.sdate').value,task_id:tr.dataset.task,start_time:tr.querySelector('.sstart').value,end_time:tr.querySelector('.send').value,positions_needed:Number(tr.querySelector('.spos').value)})});
