 root.querySelector('#tf').onsubmit=async ev=>{ev.preventDefault();const id=root.querySelector('#tid').value,p={department_id:selectedDepartment?.id||'',name:root.querySelector('#tn').value.trim(),description:root.querySelector('#desc').value.trim(),active:root.querySelector('#tactive').checked,auto_schedule:root.querySelector('#tauto').checked,eligibility:[...root.querySelectorAll('[name=elig]:checked')].map(x=>x.value)};try{await api(id?`/api/events/${cfg.eventId}/tasks/${id}`:`/api/events/${cfg.eventId}/tasks`,{method:id?'PATCH':'POST',body:JSON.stringify(p)});td.close();showTasks()}catch(e){root.querySelector('#terr').textContent=e.message}};
