 const cd=root.querySelector('#cd'); let slotRows=[],slotTasks=[],deletedSlots=new Set();
 function slotRowHtml(s,index){
   return `<tr data-i="${index}">
    <td><input class="sdate" type="date" value="${esc(s.date||event.start_date)}"></td>
    <td><select class="stask"><option value="">Select task</option>${slotTasks.filter(t=>t.active).map(t=>`<option value="${t.id}" ${s.task_id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></td>
    <td><input class="sstart" type="time" value="${esc(s.start_time||'')}"></td>
    <td><input class="send" type="time" value="${esc(s.end_time||'')}"></td>
    <td><input class="spos compact-input" type="number" min="1" max="100" value="${esc(s.positions_needed||1)}"></td>
    <td><button class="danger-soft sdelete" type="button">Delete</button></td>
   </tr>`;
 }
 function collectSlotRows(){
   const trs=[...section.querySelectorAll('#slotbody tr')];
   return trs.map(tr=>{
     const i=Number(tr.dataset.i),old=slotRows[i]||{};
     return {id:old.id||'',date:tr.querySelector('.sdate').value,task_id:tr.querySelector('.stask').value,start_time:tr.querySelector('.sstart').value,end_time:tr.querySelector('.send').value,positions_needed:Number(tr.querySelector('.spos').value)};
   });
 }
 function bindSlotRows(){
   section.querySelectorAll('.sdelete').forEach(btn=>btn.onclick=()=>{
     const tr=btn.closest('tr'),i=Number(tr.dataset.i),old=slotRows[i];
     if(old?.id)deletedSlots.add(old.id);
     const current=collectSlotRows(); current.splice(i,1); slotRows=current; drawSlots();
   });
 }
 function drawSlots(){
   const tbody=section.querySelector('#slotbody');
   if(!tbody)return;
   tbody.innerHTML=slotRows.map(slotRowHtml).join('');
   bindSlotRows();
   section.querySelector('#slot-count').textContent=`${slotRows.length} slot${slotRows.length===1?'':'s'}`;
 }
