   if(q)visible=currentSchedule.filter(a=>{const v=scheduleVolunteers.find(x=>x.id===a.volunteer_id);return ((v?.first_name||'')+' '+(v?.last_name||'')).toLowerCase().includes(q)});
   sum.textContent=q?`${visible.length} matching assignment${visible.length===1?'':'s'} · ${currentSchedule.length} total`:`${currentSchedule.length} assignment${currentSchedule.length===1?'':'s'}`;
   if(status)status.textContent=q?(visible.length?`Showing assignments for names matching “${search.value.trim()}”.`:'No volunteer assignments match this search.'):'';
   rm.classList.toggle('hidden',selectedAssignments.size===0);rm.textContent=selectedAssignments.size?`Remove Selected (${selectedAssignments.size})`:'Remove Selected';
