   box.innerHTML=`<div class="schedule-grid">${Object.values(groups).map(rows=>{const x=rows[0];return `<article class="schedule-card"><div class="schedule-card-head"><div><strong>${esc(x.task_name)}</strong><div class="muted">${esc(x.date)} · ${fmtClock(x.start_time)}${x.end_time?' – '+fmtClock(x.end_time):''}</div></div><span class="pill">${rows.length}</span></div><div class="schedule-names">${rows.map(y=>`<div class="schedule-person-row"><input class="assignment-select" type="checkbox" data-id="${y.id}" ${selectedAssignments.has(y.id)?'checked':''}><select class="assignment-volunteer" data-id="${y.id}" ${scheduleLocked?'disabled':''}>${scheduleVolunteers.map(v=>`<option value="${v.id}" ${v.id===y.volunteer_id?'selected':''}>${esc(v.first_name+' '+v.last_name)}</option>`).join('')}</select><label class="mini-lock"><input class="assignment-lock" type="checkbox" data-id="${y.id}" ${y.locked?'checked':''}><span>Lock</span></label></div>`).join('')}</div></article>`}).join('')}</div>`;
