   box.querySelectorAll('.assignment-volunteer').forEach(s=>{const original=s.value;s.onchange=async()=>{try{await api(`/api/events/${cfg.eventId}/schedule/assignments/${s.dataset.id}/volunteer`,{method:'PUT',body:JSON.stringify({volunteer_id:s.value})});showNotice('Assignment Updated','Volunteer assignment changed successfully.','success');await refreshScheduleView()}catch(e){s.value=original;showNotice('Assignment Could Not Be Changed',e.message,'error')}}});
