   host.querySelectorAll('.copy-confirm-link').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(confirmationLinks[b.dataset.id]);const old=b.textContent;b.textContent='Copied';setTimeout(()=>b.textContent=old,1200)}catch{showNotice('Copy Link','Copy the link from the field manually.','info')}});
