   if(!await askConfirm({title:'Create New Confirmation Links?',text:'OurPortal will create a secure link for every volunteer who currently has an assignment.',detail:'For security, only a SHA-256 hash is stored in the database. Creating links again replaces the previous links, so older links will stop working.',ok:'Create Links'}))return;
