   if(!await askConfirm({title:'Rebalance New Volunteers?',text:'Only active volunteers added after the schedule was locked will be considered.',detail:'OurPortal will transfer assignments from more heavily used volunteers only when the new volunteer is eligible, available, conflict-free, and the transfer improves workload balance.',ok:'Rebalance'}))return;
